import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:zan/Core/Resources/app_colors.dart';import '../../../Config/Routes/route_name.dart';import '../../../main.dart';import 'loading_splash.dart';import 'background_painter.dart';import 'build_main_details_splash.dart';class SplashBody extends StatefulWidget {  const SplashBody({super.key});  @override  State<SplashBody> createState() => _SplashBodyState();}class _SplashBodyState extends State<SplashBody> {  double logoOpacity = 0.0;  double textOpacity = 0.0;  double loadingOpacity = 0.0;  @override  void initState() {    super.initState();    SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);    _startAnimations();  }  void _startAnimations() async {    await Future.delayed(Duration(milliseconds: 300));    setState(() => logoOpacity = 1.0);    await Future.delayed(Duration(milliseconds: 300));    setState(() => textOpacity = 1.0);    await Future.delayed(Duration(milliseconds: 300));    setState(() => loadingOpacity = 1.0);    await Future.delayed(Duration(seconds: 2));    _navigateToNextScreen();  }  void _navigateToNextScreen() async {    await kNavigationService.clearAndNavigateTo(AppRoutes.boarding);  }  @override  void dispose() {    SystemChrome.setEnabledSystemUIMode(SystemUiMode.immersiveSticky);    super.dispose();  }  @override  Widget build(BuildContext context) {    return Scaffold(      backgroundColor: AppColors.primaryColor,      body: Stack(        children: [          Positioned.fill(            child: CustomPaint(              painter: BackgroundPainter(),              size: Size.infinite,            ),          ),          Positioned(              right: 0,              left: 0,              top: 188.5.h,              child: AnimatedOpacity(                duration: Duration(milliseconds: 500),                opacity: logoOpacity,                child: LogoAndText(),              )),          Positioned(            right: 0,            left: 0,            bottom: 148.h,            child: AnimatedOpacity(              duration: Duration(milliseconds: 500),              opacity: loadingOpacity,              child: Loading(),            ),          ),        ],      ),    );  }}